"""Italiano — sira (sira_001 … sira_150)."""

T = {
"sira_001": ("In quale città nacque il Profeta Muhammad ﷺ?", ["La Mecca", "Medina", "Ta'if", "Gerusalemme"], "Il Profeta Muhammad ﷺ nacque alla Mecca, nell'Hijaz."),
"sira_002": ("Come si chiama l'anno della nascita del Profeta ﷺ, segnato dall'evento dell'elefante?", ["L'Anno dell'Elefante", "L'Anno della Vittoria", "L'Anno del Cammello", "L'Anno della Luce"], "L'evento dell'elefante, in cui Allah protesse la Ka'ba, è narrato nella sura Al-Fil."),
"sira_003": ("Come si chiamava la prima moglie del Profeta ﷺ?", ["Khadija", "'Aisha", "Hafsa", "Zaynab"], "Khadija bint Khuwaylid fu la prima moglie del Profeta ﷺ e la prima persona a credere nel suo messaggio."),
"sira_004": ("In quale grotta il Profeta ﷺ ricevette la prima rivelazione?", ["La grotta di Hira", "La grotta di Thawr", "La grotta dei Compagni", "La grotta di Uhud"], "La prima rivelazione avvenne nella grotta di Hira, sul Jabal an-Nur vicino alla Mecca."),
"sira_005": ("Quale angelo portò la rivelazione al Profeta ﷺ?", ["Jibril (Gabriele)", "Mika'il (Michele)", "Israfil", "Malik"], "Il Corano menziona esplicitamente che Jibril portò la rivelazione con il permesso di Allah."),
"sira_006": ("Come si chiama la migrazione del Profeta ﷺ e dei suoi compagni dalla Mecca a Medina?", ["Al-Hijra", "Al-Isra", "Al-Mi'raj", "Al-Fath"], "Al-Hijra indica la storica migrazione a Medina, punto di partenza del calendario islamico."),
"sira_007": ("In quale città emigrarono il Profeta ﷺ e Abu Bakr?", ["Medina", "Ta'if", "Damasco", "Gerusalemme"], "Il Profeta ﷺ e Abu Bakr emigrarono dalla Mecca a Medina (allora chiamata Yathrib)."),
"sira_008": ("Il Corano descrive un compagno come «il secondo di due, quando erano nella grotta» durante la Hijra. Chi era?", ["Abu Bakr", "'Umar", "'Uthman", "'Ali"], "Il Corano si riferisce ad Abu Bakr, che accompagnò il Profeta ﷺ nella grotta di Thawr durante la Hijra."),
"sira_009": ("Quale battaglia, menzionata nel Corano, vide un piccolo esercito musulmano sconfiggere una forza molto più grande?", ["La battaglia di Badr", "La battaglia di Uhud", "La battaglia del Fossato", "La battaglia di Hunayn"], "A Badr, Allah concesse la vittoria a un piccolo gruppo di credenti contro un esercito molto più numeroso."),
"sira_010": ("Come si chiama il ritorno in gran parte pacifico del Profeta ﷺ e dei suoi compagni alla Mecca?", ["La conquista della Mecca (Fath Makkah)", "La battaglia della Mecca", "L'assedio della Mecca", "La caduta della Mecca"], "La conquista della Mecca avvenne in gran parte pacificamente, senza spargimento di sangue diffuso."),
"sira_011": ("Come si chiama l'ultimo sermone pronunciato dal Profeta ﷺ verso la fine della sua vita?", ["Il Sermone dell'Addio", "Il Sermone della Mecca", "Il Sermone della Grotta", "Il Sermone di Badr"], "Il Sermone dell'Addio (Khutbat al-Wada') fu pronunciato durante l'ultimo pellegrinaggio del Profeta ﷺ."),
"sira_012": ("In quale mese, secondo il Corano, iniziò la sua rivelazione?", ["Ramadan", "Muharram", "Rajab", "Dhul-Hijja"], "Il Corano afferma che il Ramadan è il mese in cui il Corano fu rivelato."),
"sira_013": ("Qual era la professione del Profeta ﷺ prima di ricevere la rivelazione?", ["Mercante/commerciante", "Solo pastore", "Fabbro", "Scriba"], "Il Profeta ﷺ lavorava nel commercio, un fatto ben documentato della sua biografia."),
"sira_014": ("Quale nonno del Profeta ﷺ si prese cura di lui dopo la morte della madre?", ["'Abd al-Muttalib", "Abu Talib", "Abu Lahab", "Abu Sufyan"], "'Abd al-Muttalib si prese cura del giovane Muhammad ﷺ dopo la morte della madre Amina."),
"sira_015": ("Quale zio allevò il Profeta ﷺ dopo la morte del nonno?", ["Abu Talib", "Al-'Abbas", "Hamza", "Abu Lahab"], "Abu Talib si occupò dell'educazione del nipote dopo la morte di 'Abd al-Muttalib."),
"sira_016": ("Come si chiama il viaggio notturno del Profeta ﷺ dalla Mecca a Gerusalemme, menzionato nel Corano?", ["Al-Isra", "Al-Hijra", "Al-Fath", "Al-Ghazwa"], "La sura Al-Isra si apre descrivendo questo miracoloso viaggio notturno."),
"sira_017": ("Quale figlia del Profeta ﷺ sposò 'Ali ibn Abi Talib?", ["Fatima", "Zaynab", "Ruqayya", "Umm Kulthum"], "Fatima, figlia del Profeta ﷺ e di Khadija, sposò 'Ali ibn Abi Talib: un fatto ampiamente attestato."),
"sira_018": ("Quale mese segna l'inizio dell'anno del calendario islamico, con riferimento alla Hijra?", ["Muharram", "Ramadan", "Shawwal", "Dhul-Qa'da"], "Il calendario islamico inizia con il mese di Muharram, con riferimento all'anno della Hijra."),
"sira_019": ("Chi fu il primo muezzin dell'Islam, scelto dal Profeta ﷺ per chiamare alla preghiera?", ["Bilal ibn Rabah", "Abu Bakr", "'Umar ibn al-Khattab", "Salman al-Farisi"], "Bilal, con la sua bella voce, fu scelto come primo muezzin dell'Islam."),
"sira_020": ("Quale fu la prima moschea fondata dal Profeta ﷺ al suo arrivo nei pressi di Medina?", ["La moschea di Quba", "La moschea Al-Haram", "La moschea Al-Aqsa", "La moschea delle due qibla"], "Arrivato a Quba, alle porte di Medina, il Profeta ﷺ vi fondò la prima moschea."),
"sira_021": ("Come si chiamava la madre del Profeta ﷺ?", ["Amina", "Khadija", "Halima", "Fatima"], "Amina bint Wahb era la madre del Profeta ﷺ; Halima fu la sua nutrice."),
"sira_022": ("Come si chiamava il padre del Profeta ﷺ, morto prima della sua nascita?", ["'Abdullah", "Abu Talib", "'Abd al-Muttalib", "Hamza"], "'Abdullah, figlio di 'Abd al-Muttalib, morì prima che nascesse suo figlio Muhammad ﷺ."),
"sira_023": ("Quale soprannome diedero i Meccani al Profeta ﷺ prima della rivelazione, per la sua onestà?", ["Al-Amin (il degno di fiducia)", "Al-Faruq", "As-Siddiq", "Sayf Allah"], "Già prima della rivelazione era chiamato al-Amin: la gente gli affidava i propri beni."),
"sira_024": ("In quale anno dell'Egira avvenne la conquista della Mecca?", ["L'anno 8", "L'anno 2", "L'anno 5", "L'anno 10"], "Nell'anno 8 dell'Egira il Profeta ﷺ entrò alla Mecca quasi senza combattere e perdonò i suoi abitanti."),
"sira_025": ("In quale anno dell'Egira il Profeta ﷺ compì il Pellegrinaggio dell'Addio?", ["L'anno 10", "L'anno 6", "L'anno 8", "L'anno 12"], "Il Pellegrinaggio dell'Addio avvenne nell'anno 10 dell'Egira; il Profeta ﷺ vi pronunciò il suo ultimo sermone."),
"sira_026": ("Quante figlie ebbe il Profeta ﷺ?", ["4", "1", "2", "7"], "Zaynab, Ruqayya, Umm Kulthum e Fatima: le quattro figlie del Profeta ﷺ."),
"sira_027": ("Come si chiamano gli abitanti di Medina che accolsero e aiutarono i musulmani emigrati?", ["Gli Ansar (gli Ausiliari)", "I Muhajirun", "I Quraysh", "I Tabi'un"], "Gli Ansar, «gli Ausiliari», condivisero case e beni con i loro fratelli emigrati."),
"sira_028": ("Come si chiamano i musulmani che lasciarono la Mecca per emigrare a Medina?", ["I Muhajirun (gli Emigrati)", "Gli Ansar", "Gli Hunafa'", "I Ghuzat"], "I Muhajirun lasciarono case e beni alla Mecca per preservare la loro fede."),
"sira_029": ("In quale mese avvenne la battaglia di Badr?", ["Ramadan", "Muharram", "Dhul-Hijja", "Rajab"], "La battaglia di Badr avvenne durante il Ramadan, nell'anno 2 dell'Egira."),
"sira_030": ("Prima che la qibla fosse fissata verso la Ka'ba, verso quale città pregavano i musulmani?", ["Gerusalemme (Bayt al-Maqdis)", "Medina", "Ta'if", "Damasco"], "I musulmani pregarono dapprima verso Bayt al-Maqdis; poi Allah ordinò di volgersi verso la Moschea Sacra (Corano 2:142-144)."),
"sira_031": ("A quale tribù apparteneva il Profeta Muhammad ﷺ?", ["Quraysh", "Gli Aws", "I Khazraj", "Thaqif"], "Un'intera sura porta il nome della sua tribù: Quraysh."),
"sira_032": ("Da quale clan dei Quraysh proveniva il Profeta ﷺ?", ["Banu Hashim", "Banu Umayya", "Banu Makhzum", "Banu Tamim"], "Il Profeta ﷺ apparteneva ai Banu Hashim, il clan del suo bisnonno Hashim."),
"sira_033": ("Come si chiamava la nutrice che allattò il Profeta ﷺ nel deserto?", ["Halima as-Sa'diyya", "Amina", "Khadija", "Fatima"], "Secondo l'usanza meccana, il neonato fu affidato a una nutrice beduina: Halima as-Sa'diyya."),
"sira_034": ("Quale zio del Profeta ﷺ, eroe di Badr, cadde martire a Uhud?", ["Hamza", "Abu Talib", "Al-'Abbas", "Abu Lahab"], "Hamza ibn 'Abd al-Muttalib combatté a Badr e fu ucciso nella battaglia di Uhud."),
"sira_035": ("Quale cugino del Profeta ﷺ, cresciuto nella sua casa, divenne il quarto califfo?", ["'Ali ibn Abi Talib", "Ja'far", "'Aqil", "Al-'Abbas"], "'Ali, figlio di Abu Talib, crebbe con il Profeta ﷺ e fu il quarto califfo ben guidato."),
"sira_036": ("Chi fu il primo califfo dopo la morte del Profeta ﷺ?", ["Abu Bakr", "'Umar", "'Uthman", "'Ali"], "Abu Bakr as-Siddiq fu scelto come primo califfo."),
"sira_037": ("Quale titolo porta Abu Bakr, per aver creduto al Profeta ﷺ senza esitazione?", ["As-Siddiq (il Veritiero)", "Al-Faruq", "Dhun-Nurayn", "Sayf Allah"], "Abu Bakr è chiamato as-Siddiq, colui che conferma e crede alla verità."),
"sira_038": ("Quale titolo porta 'Umar ibn al-Khattab?", ["Al-Faruq (colui che distingue il vero dal falso)", "As-Siddiq", "Dhun-Nurayn", "Al-Amin"], "'Umar è chiamato al-Faruq, colui che separa la verità dalla falsità."),
"sira_039": ("Perché 'Uthman ibn 'Affan è chiamato «Dhun-Nurayn», il possessore di due luci?", ["Sposò due figlie del Profeta ﷺ, una dopo l'altra", "Portava due lampade", "Memorizzò il Corano due volte", "Fece due hijra"], "'Uthman sposò Ruqayya e, dopo la sua morte, Umm Kulthum, entrambe figlie del Profeta ﷺ."),
"sira_040": ("In quale ordine si succedettero i quattro califfi ben guidati?", ["Abu Bakr, 'Umar, 'Uthman, 'Ali", "'Ali, 'Umar, Abu Bakr, 'Uthman", "'Umar, Abu Bakr, 'Ali, 'Uthman", "Abu Bakr, 'Ali, 'Umar, 'Uthman"], "Abu Bakr, poi 'Umar, poi 'Uthman, poi 'Ali."),
"sira_041": ("Chi fu la prima persona a credere nel messaggio del Profeta ﷺ?", ["Khadija, sua moglie", "Abu Bakr", "'Ali", "Bilal"], "Khadija credette in lui fin dalla prima rivelazione e lo sostenne."),
"sira_042": ("Chi comprò Bilal per liberarlo dalle torture del suo padrone?", ["Abu Bakr", "'Umar", "Hamza", "'Uthman"], "Abu Bakr comprò Bilal e lo liberò."),
"sira_043": ("Chi fu la prima martire dell'Islam, uccisa alla Mecca per la sua fede?", ["Sumayya, madre di 'Ammar", "Asma", "Umm Salama", "Safiyya"], "Sumayya bint Khayyat, madre di 'Ammar ibn Yasir, fu uccisa da Abu Jahl."),
"sira_044": ("Verso quale terra avvenne la prima emigrazione dei musulmani perseguitati alla Mecca?", ["L'Abissinia (Etiopia)", "La Persia", "Lo Yemen", "L'Egitto"], "I primi emigrati andarono in Abissinia, presso un re giusto."),
"sira_045": ("Come si chiamava il re d'Abissinia che protesse i musulmani e per il quale il Profeta ﷺ pregò la preghiera funebre in assenza?", ["An-Najashi (il Negus)", "Eraclio", "Cosroe", "Al-Muqawqis"], "Il Profeta ﷺ annunciò la morte del Negus il giorno stesso e pregò per lui con i compagni."),
"sira_046": ("Quale compagno parlò davanti al Negus per spiegare l'Islam?", ["Ja'far ibn Abi Talib", "'Uthman", "Bilal", "Mus'ab ibn 'Umayr"], "Ja'far spiegò al re ciò che insegnava il Profeta ﷺ e gli recitò versetti della sura Maryam."),
"sira_047": ("Quale zio del Profeta ﷺ è condannato per nome nel Corano?", ["Abu Lahab", "Abu Talib", "Al-'Abbas", "Hamza"], "«Periscano le mani di Abu Lahab, e perisca lui.»"),
"sira_048": ("Come si chiama l'anno in cui il Profeta ﷺ perse la moglie Khadija e lo zio Abu Talib?", ["L'Anno del Dolore", "L'Anno dell'Elefante", "L'Anno delle Delegazioni", "L'Anno della Carestia"], "I due grandi sostegni del Profeta ﷺ morirono nello stesso anno, noto come l'Anno del Dolore."),
"sira_049": ("In quale città il Profeta ﷺ fu cacciato e ferito dopo aver chiamato all'Islam, prima di rifiutare che l'angelo delle montagne ne schiacciasse gli abitanti?", ["At-Ta'if", "Medina", "Khaybar", "Tabuk"], "Respinto a Ta'if, rifiutò di distruggerne gli abitanti, sperando che i loro discendenti adorassero Allah."),
"sira_050": ("Durante il Viaggio notturno e l'Ascensione (Isra e Mi'raj), quale obbligo fu prescritto ai musulmani?", ["Le cinque preghiere quotidiane", "Il digiuno del Ramadan", "La zakat", "Il pellegrinaggio"], "Le preghiere furono prescritte quella notte, ridotte da cinquanta a cinque, con la ricompensa di cinquanta."),
"sira_051": ("Quale albero, al limite estremo, vide il Profeta ﷺ durante l'Ascensione, secondo la sura An-Najm?", ["Sidrat al-Muntaha", "L'ulivo benedetto", "La palma di Maryam", "L'albero di Tuba"], "«Presso Sidrat al-Muntaha», il loto del limite estremo."),
"sira_052": ("Come si chiamano i giuramenti di fedeltà che la gente di Yathrib prestò al Profeta ﷺ prima della Hijra?", ["I giuramenti di Al-'Aqaba", "Il patto di Hudaybiyya", "Il giuramento dell'albero", "La Costituzione di Medina"], "Gente di Yathrib giurò fedeltà al Profeta ﷺ ad Al-'Aqaba, vicino a Mina, prima della Hijra."),
"sira_053": ("Quale compagno inviò il Profeta ﷺ a Yathrib, prima della Hijra, per insegnare l'Islam?", ["Mus'ab ibn 'Umayr", "Bilal", "Abu Hurayra", "Khalid ibn al-Walid"], "Mus'ab ibn 'Umayr fu il primo inviato a Yathrib, dove insegnò il Corano ai nuovi musulmani."),
"sira_054": ("Chi dormì nel letto del Profeta ﷺ la notte in cui partì per la Hijra?", ["'Ali ibn Abi Talib", "Abu Bakr", "Zayd ibn Haritha", "Bilal"], "'Ali prese il suo posto nel letto per ingannare chi sorvegliava, poi restituì i depositi ai Meccani."),
"sira_055": ("In quale grotta si nascosero il Profeta ﷺ e Abu Bakr durante la Hijra?", ["La grotta di Thawr", "La grotta di Hira", "La grotta di Uhud", "La grotta di Ta'if"], "Si nascosero per tre giorni nella grotta di Thawr, a sud della Mecca."),
"sira_056": ("Quale figlia di Abu Bakr portò provviste alla grotta e fu soprannominata «quella delle due cinture»?", ["Asma", "'Aisha", "Umm Kulthum", "Umm Ruman"], "Asma strappò in due la sua cintura per legare le provviste: da qui «Dhat an-Nitaqayn»."),
"sira_057": ("Che cosa accadde a Suraqa, che inseguì il Profeta ﷺ durante la Hijra?", ["Il suo cavallo sprofondò nel terreno, ed egli chiese salvezza", "Raggiunse il Profeta ﷺ", "Si perse nel deserto", "Si ammalò"], "Le zampe del suo cavallo sprofondarono nella terra; Suraqa chiese un salvacondotto e se ne andò senza far male."),
"sira_058": ("Qual era l'antico nome di Medina, menzionato nel Corano?", ["Yathrib", "Tayba", "Khaybar", "Bakka"], "«O gente di Yathrib…», dice il Corano, ricordando la battaglia dei confederati."),
"sira_059": ("Come si chiamava la cammella del Profeta ﷺ, che si inginocchiò a Hudaybiyya?", ["Al-Qaswa", "Al-Buraq", "Ad-Duldul", "Al-'Adba"], "A Hudaybiyya, Al-Qaswa si inginocchiò; il Profeta ﷺ disse: «Colui che trattenne l'elefante l'ha trattenuta.»"),
"sira_060": ("Che cosa stabilì il Profeta ﷺ tra i Muhajirun e gli Ansar all'arrivo a Medina?", ["La fratellanza, a coppie", "Una tassa", "Un esercito", "Un mercato"], "Rese fratelli gli emigrati e gli ausiliari, ogni Muhajir unito a un fratello tra gli Ansar."),
"sira_061": ("Come si chiama il documento con cui il Profeta ﷺ organizzò i rapporti tra le comunità di Medina?", ["La Sahifa (Costituzione) di Medina", "Il trattato di Hudaybiyya", "Il patto di Ta'if", "La carta di Quba"], "La Sahifa stabiliva i diritti e i doveri dei musulmani e delle altre tribù di Medina."),
"sira_062": ("Come erano chiamati i compagni poveri che vivevano nella moschea del Profeta ﷺ?", ["Ahl as-Suffa (la gente della panca)", "I Muhajirun", "Gli Ansar", "Gli Hawariyyun"], "Abu Hurayra racconta di essere stato tra la gente della Suffa, nutrita dal Profeta ﷺ."),
"sira_063": ("Quanti anni dopo la Hijra avvenne la battaglia di Badr?", ["Due", "Cinque", "Otto", "Dieci"], "Badr fu combattuta nell'anno 2 dell'Egira, durante il Ramadan."),
"sira_064": ("Quanti angeli Allah promise di inviare come rinforzo ai credenti a Badr?", ["Mille", "Cento", "Dieci", "Centomila"], "«Vi rinforzerò con mille angeli, che si susseguono.»"),
"sira_065": ("A Uhud, quale errore degli arcieri capovolse la battaglia?", ["Lasciarono la collina nonostante l'ordine del Profeta ﷺ", "Tirarono troppo presto", "Si addormentarono", "Cambiarono schieramento"], "Il Profeta ﷺ aveva ordinato agli arcieri di non muoversi; la maggior parte scese per il bottino e la cavalleria nemica li aggirò."),
"sira_066": ("Vicino a quale città si trova il monte Uhud?", ["Medina", "La Mecca", "Ta'if", "Gerusalemme"], "Il monte Uhud si trova a nord di Medina; la battaglia si svolse ai suoi piedi."),
"sira_067": ("Quale compagno suggerì di scavare un fossato per difendere Medina dai confederati?", ["Salman al-Farisi", "Bilal", "Abu Dharr", "Suhayb"], "Salman il Persiano suggerì il fossato, una tattica nota in Persia."),
"sira_068": ("Con quale altro nome è nota la battaglia del Fossato, dalla sura che ne parla?", ["La battaglia dei Confederati (Al-Ahzab)", "La battaglia di Badr", "La battaglia di Hunayn", "La battaglia di Mu'ta"], "La sura Al-Ahzab ricorda gli eserciti alleati che assediarono Medina e il vento inviato contro di loro."),
"sira_069": ("Come si chiama il giuramento prestato sotto un albero a Hudaybiyya, di cui Allah dice di essersi compiaciuto?", ["Bay'at ar-Ridwan", "Bay'at al-'Aqaba", "Bay'at an-Nisa", "Bay'at al-Fath"], "«Allah si è compiaciuto dei credenti quando ti hanno giurato fedeltà sotto l'albero.»"),
"sira_070": ("Quale sura si apre con «Ti abbiamo concesso una vittoria evidente», rivelata dopo il trattato di Hudaybiyya?", ["Al-Fath", "An-Nasr", "Al-Anfal", "At-Tawba"], "«In verità, ti abbiamo concesso una vittoria evidente»: la sura Al-Fath."),
"sira_071": ("In quale anno dell'Egira fu concluso il trattato di Hudaybiyya?", ["6 dell'Egira", "2 dell'Egira", "8 dell'Egira", "10 dell'Egira"], "Il trattato di Hudaybiyya fu concluso nell'anno 6 dell'Egira tra i musulmani e i Quraysh."),
"sira_072": ("Quale imperatore bizantino ricevette la lettera del Profeta ﷺ che lo invitava all'Islam e interrogò Abu Sufyan su di lui?", ["Eraclio", "Nerone", "Costantino", "Giustiniano"], "Eraclio interrogò Abu Sufyan sul Profeta ﷺ dopo aver ricevuto la sua lettera."),
"sira_073": ("A chi consegnò il Profeta ﷺ lo stendardo a Khaybar, dopo aver detto: «Domani lo darò a un uomo che Allah e il Suo Messaggero amano»?", ["'Ali ibn Abi Talib", "Abu Bakr", "'Umar", "Sa'd ibn Abi Waqqas"], "Chiamò 'Ali, che aveva male agli occhi; applicò la sua saliva, lo guarì e gli diede lo stendardo."),
"sira_074": ("Quali tre comandanti caddero uno dopo l'altro nella battaglia di Mu'ta?", ["Zayd ibn Haritha, Ja'far ibn Abi Talib e 'Abdullah ibn Rawaha", "Hamza, Mus'ab e Sa'd", "Abu Bakr, 'Umar e 'Uthman", "Bilal, Salman e Suhayb"], "Il Profeta ﷺ annunciò a Medina: «Zayd prese lo stendardo e cadde, poi Ja'far, poi Ibn Rawaha… poi lo prese una spada di Allah.»"),
"sira_075": ("Quale compagno il Profeta ﷺ chiamò «una spada tra le spade di Allah»?", ["Khalid ibn al-Walid", "'Ali", "Hamza", "Abu 'Ubayda"], "A Mu'ta, «una spada tra le spade di Allah», Khalid ibn al-Walid, prese lo stendardo e salvò l'esercito."),
"sira_076": ("Che cosa fece il Profeta ﷺ degli idoli intorno alla Ka'ba alla conquista della Mecca?", ["Li abbatté recitando «La verità è giunta e la falsità è svanita»", "Li vendette", "Li portò a Medina", "Li lasciò al loro posto"], "Colpì gli idoli con il suo bastone dicendo: «La verità è giunta e la falsità è svanita.»"),
"sira_077": ("Chi fece la chiamata alla preghiera dall'alto della Ka'ba il giorno della conquista della Mecca?", ["Bilal", "Abu Bakr", "'Ali", "'Umar"], "Il Profeta ﷺ ordinò a Bilal di salire sulla Ka'ba e chiamare alla preghiera."),
"sira_078": ("Che cosa disse il Profeta ﷺ ai Meccani sconfitti che lo avevano perseguitato, il giorno della conquista?", ["«Andate, siete liberi»", "«Sarete giudicati domani»", "«Lasciate la città»", "«Pagate un riscatto»"], "Li perdonò: «Andate, siete liberi.»"),
"sira_079": ("In quale battaglia, nominata nel Corano, i musulmani furono dapprima colti di sorpresa nonostante il loro gran numero?", ["Hunayn", "Badr", "Uhud", "Khaybar"], "«Il giorno di Hunayn, il vostro gran numero vi compiacque, ma non vi servì a nulla.»"),
"sira_080": ("Quale compagno, rimasto indietro dalla spedizione di Tabuk, confessò onestamente e fu perdonato da una rivelazione?", ["Ka'b ibn Malik", "Abu Dharr", "Anas ibn Malik", "Abu Hurayra"], "Ka'b ibn Malik disse la verità, sopportò cinquanta giorni di isolamento, poi Allah rivelò il suo perdono (9:118)."),
"sira_081": ("Come si chiama l'anno 9 dell'Egira, in cui molte tribù vennero a Medina per abbracciare l'Islam?", ["L'Anno delle Delegazioni", "L'Anno del Dolore", "L'Anno dell'Elefante", "L'Anno della Siccità"], "Dopo la conquista della Mecca, delegazioni di tribù arabe affluirono a Medina."),
"sira_082": ("Dove pronunciò il Profeta ﷺ il Sermone dell'Addio?", ["Ad Arafat", "A Medina", "Sul monte Uhud", "A Ta'if"], "Il Sermone dell'Addio fu pronunciato ad Arafat, durante il Pellegrinaggio dell'Addio."),
"sira_083": ("Quale versetto, rivelato durante il Pellegrinaggio dell'Addio, annuncia che la religione è perfezionata?", ["«Oggi ho perfezionato per voi la vostra religione»", "«Leggi, nel nome del tuo Signore»", "«Quando giunge la vittoria di Allah»", "«Di': Egli è Allah, Uno»"], "«Oggi ho perfezionato per voi la vostra religione e ho completato su di voi il Mio favore.»"),
"sira_084": ("In quale città morì e fu sepolto il Profeta ﷺ?", ["Medina", "La Mecca", "Gerusalemme", "Ta'if"], "Morì a Medina nell'anno 11 dell'Egira e vi fu sepolto."),
"sira_085": ("Nella stanza di quale moglie fu sepolto il Profeta ﷺ?", ["Di 'Aisha", "Di Khadija", "Di Hafsa", "Di Umm Salama"], "Fu sepolto dove morì, nella stanza di 'Aisha, oggi all'interno della Moschea del Profeta."),
"sira_086": ("Chi dichiarò, alla morte del Profeta ﷺ: «Chi adorava Muhammad, Muhammad è morto; chi adora Allah, Allah è il Vivente»?", ["Abu Bakr", "'Umar", "'Ali", "Bilal"], "Abu Bakr calmò i compagni e recitò: «Muhammad non è che un messaggero…» (3:144)."),
"sira_087": ("Come si chiamavano i due nipoti del Profeta ﷺ, figli di Fatima e 'Ali?", ["Al-Hasan e Al-Husayn", "Ibrahim e Isma'il", "Zayd e Usama", "Ja'far e 'Aqil"], "Al-Hasan e Al-Husayn, che il Profeta ﷺ amava teneramente."),
"sira_088": ("Quale moglie del Profeta ﷺ era figlia di Abu Bakr?", ["'Aisha", "Hafsa", "Zaynab", "Sawda"], "'Aisha, figlia di Abu Bakr, trasmise un numero molto grande di hadith."),
"sira_089": ("Quale moglie del Profeta ﷺ era figlia di 'Umar ibn al-Khattab?", ["Hafsa", "'Aisha", "Umm Habiba", "Maymuna"], "Hafsa bint 'Umar; la prima copia raccolta del Corano fu custodita presso di lei."),
"sira_090": ("Quale compagno riferì il maggior numero di hadith dal Profeta ﷺ?", ["Abu Hurayra", "Anas ibn Malik", "'Abdullah ibn 'Umar", "Jabir"], "Abu Hurayra, che frequentò assiduamente il Profeta ﷺ, è il compagno che riferì più hadith."),
"sira_091": ("Quale giovane compagno servì il Profeta ﷺ per dieci anni senza mai sentire un rimprovero?", ["Anas ibn Malik", "Usama ibn Zayd", "Ibn 'Abbas", "Zayd ibn Thabit"], "Anas disse: «Ho servito il Profeta ﷺ per dieci anni; non mi ha mai detto 'uff', né 'perché l'hai fatto?'»"),
"sira_092": ("Per quale giovane cugino pregò il Profeta ﷺ: «O Allah, insegnagli il Libro»?", ["'Abdullah ibn 'Abbas", "'Ali", "Ja'far", "Usama"], "Il Profeta ﷺ abbracciò Ibn 'Abbas e disse: «O Allah, insegnagli il Libro.»"),
"sira_093": ("Quale compagno inviò il Profeta ﷺ nello Yemen, dicendogli di chiamare prima all'unicità di Allah?", ["Mu'adh ibn Jabal", "Bilal", "Solo Abu Musa", "Zayd ibn Haritha"], "«Vai da un popolo del Libro: chiamali prima a testimoniare che non c'è dio all'infuori di Allah…»"),
"sira_094": ("Quale compagno il Profeta ﷺ chiamò «il fidato (amin) di questa comunità»?", ["Abu 'Ubayda ibn al-Jarrah", "Abu Bakr", "'Uthman", "Khalid"], "«Ogni comunità ha un fidato, e il fidato di questa comunità è Abu 'Ubayda ibn al-Jarrah.»"),
"sira_095": ("Quale compagno, scriba della rivelazione, fu incaricato da Abu Bakr di raccogliere il Corano?", ["Zayd ibn Thabit", "Abu Hurayra", "Anas ibn Malik", "Salman"], "Dopo la battaglia di al-Yamama, Abu Bakr incaricò Zayd ibn Thabit di raccogliere il Corano."),
"sira_096": ("Sotto quale califfo furono inviate copie ufficiali del Corano alle province?", ["'Uthman ibn 'Affan", "Abu Bakr", "'Umar", "'Ali"], "'Uthman fece copiare il mushaf e ne inviò una copia a ogni provincia."),
"sira_097": ("Da quale terra veniva il compagno Salman, chiamato «al-Farisi»?", ["La Persia", "L'Abissinia", "Bisanzio", "Lo Yemen"], "Salman al-Farisi, «il Persiano», venne dalla Persia in cerca della verità."),
"sira_098": ("Quale compagno, venuto dalle terre bizantine, è chiamato «ar-Rumi»?", ["Suhayb", "Bilal", "Salman", "Abu Dharr"], "Suhayb ar-Rumi crebbe tra i Bizantini prima di abbracciare l'Islam alla Mecca."),
"sira_099": ("Come si chiama la moschea del Profeta ﷺ a Medina?", ["Al-Masjid an-Nabawi", "Al-Masjid al-Haram", "Al-Masjid al-Aqsa", "Masjid Quba"], "La moschea che fondò a Medina è chiamata Moschea del Profeta, al-Masjid an-Nabawi."),
"sira_100": ("Quante volte compare il nome «Muhammad» nel Corano?", ["Quattro", "Una", "Dodici", "Cento"], "Nei versetti 3:144, 33:40, 47:2 e 48:29; il nome «Ahmad» compare in 61:6."),
"sira_101": ("Come descrive il Corano il Profeta ﷺ per i credenti, nel versetto 33:21?", ["Un eccellente esempio", "Un giudice severo", "Un re", "Un poeta"], "«Avete certamente nel Messaggero di Allah un eccellente esempio.»"),
"sira_102": ("Qual era la kunya (soprannome paterno) del Profeta ﷺ?", ["Abu al-Qasim", "Abu Bakr", "Abu 'Abdullah", "Abu Talib"], "Era chiamato Abu al-Qasim, dal nome del suo figlio maggiore Al-Qasim."),
"sira_103": ("Come si chiamava il figlio del Profeta ﷺ nato a Medina, morto da bambino?", ["Ibrahim", "Al-Qasim", "'Abdullah", "Al-Hasan"], "Ibrahim, nato a Medina, morì neonato; il Profeta ﷺ pianse e disse che il cuore si addolora senza dire ciò che dispiace ad Allah."),
"sira_104": ("Per conto di chi il Profeta ﷺ guidò una carovana commerciale in Siria prima della rivelazione?", ["Khadija", "Abu Bakr", "Abu Sufyan", "Al-'Abbas"], "Khadija, ricca mercante, gli affidò la sua carovana per la Siria, poi gli propose il matrimonio."),
"sira_105": ("Come risolse il giovane Muhammad ﷺ la disputa dei clan sulla ricollocazione della Pietra Nera?", ["La pose su un panno che ogni clan sollevò, poi la sistemò lui stesso", "La portò da solo", "Tirò a sorte", "La affidò ad Abu Bakr"], "Stese un mantello, vi pose la Pietra, fece sollevare il panno insieme ai capi dei clan, poi la collocò con la propria mano."),
"sira_106": ("A che età il Profeta ﷺ ricevette la prima rivelazione?", ["Quaranta", "Venticinque", "Cinquanta", "Sessanta"], "La rivelazione iniziò quando aveva quarant'anni, nella grotta di Hira."),
"sira_107": ("Da quale cugino di Khadija, dotto nelle Scritture, fu condotto il Profeta ﷺ dopo la prima rivelazione?", ["Waraqa ibn Nawfal", "Abu Talib", "Abu Lahab", "Al-Walid"], "Waraqa disse: «Questo è il Namus (l'angelo) che Allah inviò a Musa.»"),
"sira_108": ("Su quale collina salì il Profeta ﷺ per chiamare pubblicamente i Quraysh, dopo il versetto «Ammonisci i tuoi parenti più stretti»?", ["As-Safa", "Uhud", "Arafat", "Hira"], "Salì su as-Safa, chiamò i clan dei Quraysh e li avvertì di un castigo severo."),
"sira_109": ("Quale califfo istituì il calendario musulmano a partire dall'anno della Hijra?", ["'Umar ibn al-Khattab", "Abu Bakr", "'Uthman", "'Ali"], "Sotto 'Umar, la Hijra fu scelta come punto di partenza del calendario."),
"sira_110": ("Quanti anni visse il Profeta ﷺ a Medina dopo la Hijra?", ["Dieci", "Tre", "Venti", "Tredici"], "Visse dieci anni a Medina, dalla Hijra alla sua morte nell'anno 11 dell'Egira."),
"sira_111": ("Per quanti anni il Profeta ﷺ predicò alla Mecca prima della Hijra?", ["Tredici", "Tre", "Dieci", "Ventitré"], "Tredici anni alla Mecca, poi dieci a Medina: ventitré anni di missione."),
"sira_112": ("Quale compagno, poeta, difese il Profeta ﷺ con i suoi versi e per il quale egli chiese il sostegno di Jibril?", ["Hassan ibn Thabit", "Ka'b ibn Malik", "'Abdullah ibn Rawaha", "Labid"], "Il Profeta ﷺ disse a Hassan: «Rispondi loro, e Jibril è con te.»"),
"sira_113": ("Di quale compagno il Profeta ﷺ disse che gli era stato dato «uno dei flauti della famiglia di Dawud» per la sua bella recitazione?", ["Abu Musa al-Ash'ari", "Bilal", "Ubayy ibn Ka'b", "Ibn Mas'ud"], "Sentendolo recitare, il Profeta ﷺ disse che ad Abu Musa era stato dato uno dei flauti della famiglia di Dawud."),
"sira_114": ("Il Profeta ﷺ raccomandò di imparare il Corano da quattro compagni. Quale di questi era uno di loro?", ["'Abdullah ibn Mas'ud", "Abu Hurayra", "Anas ibn Malik", "Khalid ibn al-Walid"], "«Imparate il Corano da quattro: Ibn Mas'ud, Salim, Mu'adh ibn Jabal e Ubayy ibn Ka'b.»"),
"sira_115": ("In quale battaglia il Profeta ﷺ fu ferito al volto e perse un dente?", ["Uhud", "Badr", "Hunayn", "Khaybar"], "A Uhud, un suo dente si ruppe e il suo volto fu ferito."),
"sira_116": ("A quale compagno, arciere a Uhud, il Profeta ﷺ disse: «Tira! Mio padre e mia madre siano il tuo riscatto»?", ["Sa'd ibn Abi Waqqas", "Talha", "Az-Zubayr", "'Ali"], "Il Profeta ﷺ gli porgeva le frecce dicendo: «Tira, mio padre e mia madre siano sacrificati per te.»"),
"sira_117": ("Quale carovana partirono a intercettare i musulmani, cosa che portò alla battaglia di Badr?", ["Quella di Abu Sufyan, di ritorno dalla Siria", "Quella del Negus", "Quella dei Persiani", "Quella di Ta'if"], "La carovana dei Quraysh guidata da Abu Sufyan sfuggì, ma l'esercito meccano venne a Badr."),
"sira_118": ("Quando abbracciò l'Islam il capo meccano Abu Sufyan?", ["Alla conquista della Mecca", "Prima della Hijra", "A Badr", "Dopo la morte del Profeta ﷺ"], "Abu Sufyan si convertì alla vigilia dell'ingresso del Profeta ﷺ alla Mecca."),
"sira_119": ("Quale sorgente sgorgò per Hajar e suo figlio Isma'il nella valle della Mecca?", ["Zamzam", "Il Nilo", "L'Eufrate", "Il Giordano"], "Un angelo colpì il suolo e l'acqua di Zamzam sgorgò; Hajar vi fece attorno un bacino."),
"sira_120": ("Che cosa era inciso sull'anello del Profeta ﷺ?", ["«Muhammad Rasul Allah»", "«Allahu Akbar»", "«La ilaha illa Allah»", "Solo il suo nome"], "Il suo anello d'argento portava «Muhammad, Messaggero di Allah» su tre righe."),
"sira_121": ("Quali cibi amava il Profeta ﷺ, secondo 'Aisha?", ["I dolci e il miele", "Il pesce", "Le spezie forti", "Solo l'aceto"], "'Aisha riferisce che il Profeta ﷺ amava le cose dolci e il miele."),
"sira_122": ("In quale giorno della settimana nacque il Profeta ﷺ, giorno in cui anche digiunava?", ["Lunedì", "Venerdì", "Sabato", "Mercoledì"], "Interrogato sul digiuno del lunedì, disse: «È il giorno in cui sono nato e il giorno in cui mi è giunta la rivelazione.»"),
"sira_123": ("Dove si trovava il «sigillo della profezia» sul corpo del Profeta ﷺ?", ["Tra le spalle", "Sulla mano", "Sulla fronte", "Sul petto"], "Il sigillo della profezia era tra le sue spalle."),
"sira_124": ("Con quale legno fu costruito il minbar (pulpito) del Profeta ﷺ, da un falegname?", ["Tamerice (athl)", "Cedro", "Ulivo", "Palma"], "Il Profeta ﷺ fece costruire un minbar di legno di tamerice, dal quale si rivolgeva alla gente."),
"sira_125": ("Quali due grandi tribù di Medina formarono gli Ansar?", ["Gli Aws e i Khazraj", "I Quraysh e i Thaqif", "I Tamim e gli Hawazin", "I Kinda e gli Hamdan"], "Gli Aws e i Khazraj, rivali da lungo tempo, si unirono nell'Islam e divennero gli Ansar."),
"sira_126": ("Quale titolo dà il Corano alle mogli del Profeta ﷺ?", ["Le Madri dei Credenti", "Le regine di Medina", "Le figlie dei Quraysh", "Le custodi del Libro"], "«Le sue mogli sono le loro madri»: le Madri dei Credenti."),
"sira_127": ("In quale anno del calendario cristiano avvenne la Hijra?", ["622", "570", "632", "610"], "La Hijra, nel 622, segna l'inizio del calendario musulmano."),
"sira_128": ("Che cosa rispose 'Abd ar-Rahman ibn 'Awf quando il suo fratello Ansari gli offrì metà dei suoi beni?", ["«Indicami il mercato»", "Accettò tutto", "Chiese una casa", "Rifiutò di parlare"], "Disse: «Allah benedica i tuoi beni e la tua famiglia; indicami solo il mercato», e prosperò con il commercio."),
"sira_129": ("A quale compagno il Profeta ﷺ chiese quale versetto del Corano fosse il più grande, prima di congratularsi per la sua risposta (il Versetto del Trono)?", ["Ubayy ibn Ka'b", "Abu Bakr", "Zayd ibn Thabit", "Bilal"], "Ubayy rispose: «Allah, non c'è dio all'infuori di Lui, il Vivente…»; il Profeta ﷺ disse: «Che la conoscenza ti rallegri, Abu al-Mundhir!»"),
"sira_130": ("Come fu scelto il luogo della moschea del Profeta ﷺ a Medina?", ["Dove si inginocchiò la sua cammella", "Tirando a sorte", "Al centro del mercato", "Sul monte Uhud"], "Lasciò camminare liberamente la sua cammella: dove si inginocchiò, fu costruita la moschea."),
"sira_131": ("Quanti figli maschi ebbe il Profeta ﷺ, tutti morti in tenera età?", ["Tre", "Uno", "Cinque", "Nessuno"], "Al-Qasim e 'Abdullah, nati da Khadija, e Ibrahim, nato a Medina."),
"sira_132": ("Quale compagno, liberato dal Profeta ﷺ e cresciuto come un figlio, fu il padre di Usama?", ["Zayd ibn Haritha", "Bilal", "Salman", "'Ammar"], "Zayd ibn Haritha, amato dal Profeta ﷺ, fu il padre di Usama ibn Zayd."),
"sira_133": ("Quale giovane compagno il Profeta ﷺ nominò alla guida di un esercito poco prima della sua morte, nonostante la giovane età?", ["Usama ibn Zayd", "Anas ibn Malik", "Ibn 'Abbas", "Ibn 'Umar"], "Il Profeta ﷺ diede il comando a Usama e rispose a chi criticava la sua età che ne era degno, come suo padre."),
"sira_134": ("Quale nonno del Profeta ﷺ scavò di nuovo il pozzo di Zamzam, da tempo interrato?", ["'Abd al-Muttalib", "Hashim", "'Abd Manaf", "Qusayy"], "'Abd al-Muttalib riscavò Zamzam e se ne prese cura per i pellegrini."),
"sira_135": ("Circa quante persone accompagnarono il Profeta ﷺ nella battaglia di Badr?", ["Poco più di trecento", "Diecimila", "Mille", "Cinquanta"], "I musulmani a Badr erano poco più di trecento, di fronte a un esercito molto più grande."),
"sira_136": ("In quale mese del calendario musulmano nacque il Profeta ﷺ?", ["Rabi' al-Awwal", "Ramadan", "Muharram", "Dhul-Hijja"], "Nacque nel mese di Rabi' al-Awwal, nell'Anno dell'Elefante."),
"sira_137": ("In quale mese il Profeta ﷺ arrivò a Medina durante la Hijra?", ["Rabi' al-Awwal", "Ramadan", "Muharram", "Rajab"], "Arrivò a Medina in Rabi' al-Awwal, dopo essersi fermato a Quba."),
"sira_138": ("Quale patto fecero i Quraysh per isolare i Banu Hashim, che proteggevano il Profeta ﷺ?", ["Un boicottaggio: nessun commercio né matrimonio con loro", "Una tregua di dieci anni", "Una spartizione della Ka'ba", "Un'alleanza militare"], "I Quraysh firmarono un patto di boicottaggio, e i Banu Hashim furono confinati in una valle per anni."),
"sira_139": ("Come iniziò il Profeta ﷺ la sua missione alla Mecca, prima della chiamata pubblica?", ["Chiamando discretamente la sua cerchia ristretta", "Con un esercito", "Con una lettera ai re", "Con un pellegrinaggio"], "Chiamò dapprima in privato i suoi parenti e amici, prima che la chiamata diventasse pubblica."),
"sira_140": ("Tra quali due colline corse Hajar cercando acqua per Isma'il?", ["As-Safa e Al-Marwa", "Uhud e Thawr", "Arafat e Mina", "Hira e Thawr"], "Corse sette volte tra as-Safa e al-Marwa: l'origine del sa'y dei pellegrini."),
"sira_141": ("Di quale nipote il Profeta ﷺ disse: «Questo mio figlio è un sayyid; Allah riconcilierà tramite lui due gruppi di musulmani»?", ["Al-Hasan", "Al-Husayn", "Usama", "Ibn 'Abbas"], "Al-Hasan ibn 'Ali riconciliò in seguito due grandi gruppi di musulmani, come il Profeta ﷺ aveva predetto."),
"sira_142": ("Come si chiamava la figlia del Profeta ﷺ, madre di Al-Hasan e Al-Husayn?", ["Fatima", "Zaynab", "Ruqayya", "Umm Kulthum"], "Fatima, moglie di 'Ali, fu la madre di Al-Hasan e Al-Husayn."),
"sira_143": ("Chi era la figlia maggiore del Profeta ﷺ?", ["Zaynab", "Fatima", "Ruqayya", "Umm Kulthum"], "Zaynab era la maggiore delle quattro figlie del Profeta ﷺ."),
"sira_144": ("Quale compagno, ex schiavo di origine abissina, fu scelto come muezzin per la sua bella voce?", ["Bilal ibn Rabah", "Salman", "Suhayb", "Zayd"], "Bilal, liberato da Abu Bakr, divenne il muezzin del Profeta ﷺ."),
"sira_145": ("Di quale compagno il Profeta ﷺ disse: «Se dovessi prendere un amico intimo (khalil) tra gli uomini, sarebbe lui»?", ["Abu Bakr", "'Umar", "'Ali", "'Uthman"], "«Se dovessi prendere un amico intimo dalla mia comunità, prenderei Abu Bakr, ma egli è mio fratello e compagno.»"),
"sira_146": ("Quale città, insieme alla Mecca, è chiamata «al-Haramayn», i due santuari?", ["Medina", "Gerusalemme", "Ta'if", "Damasco"], "La Mecca e Medina sono le due città sante, al-Haramayn."),
"sira_147": ("Quante volte il Profeta ﷺ compì lo Hajj dopo la Hijra?", ["Una volta, il Pellegrinaggio dell'Addio", "Tre volte", "Ogni anno", "Mai"], "Compì un solo Hajj dopo la Hijra: il Pellegrinaggio dell'Addio, nell'anno 10 dell'Egira."),
"sira_148": ("Secondo Anas, che cosa fece il Profeta ﷺ quando un beduino tirò con forza il suo mantello chiedendo dei beni?", ["Sorrise e ordinò che gli fosse dato qualcosa", "Lo fece punire", "Se ne andò senza una parola", "Lo cacciò"], "Il Profeta ﷺ si voltò verso di lui, rise e ordinò che gli fosse dato qualcosa."),
"sira_149": ("Quale città, sede della moschea al-Aqsa, fu la destinazione del Viaggio notturno?", ["Gerusalemme", "Damasco", "Il Cairo", "Baghdad"], "Il Viaggio notturno portò il Profeta ﷺ dalla Mecca alla moschea al-Aqsa a Gerusalemme."),
"sira_150": ("Quanti anni aveva il Profeta ﷺ quando morì?", ["Sessantatré", "Quaranta", "Cinquanta", "Ottanta"], "Morì all'età di sessantatré anni, nell'anno 11 dell'Egira."),
}
